"""Build deterministik portal dan seluruh topik, tanpa dependensi eksternal."""
from pathlib import Path
from html import escape as e
import json
from course_data import TOPICS,MEETINGS
from course_visuals import visual
ROOT=Path(__file__).parent
def save(path,text):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def nav(prefix):
 links=''.join(f'<a href="{prefix}topik/{t["slug"]}/index.html">{i:02} · {e(t["title"])}</a>' for i,t in enumerate(TOPICS,1))
 return f'<header class="header"><div class="wrap nav"><a class="brand" href="{prefix}index.html">Inkuiri<span>Lab</span> / IPA</a><nav aria-label="Navigasi utama"><a href="{prefix}semester.html">Peta semester</a><details class="topic-menu"><summary>Menu topik</summary><div>{links}</div></details></nav></div></header>'
def page(title,body,prefix='',script=''):
 return f'<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Materi konseptual dan visual Konsep Dasar IPA untuk PGMI"><title>{e(title)} · Konsep Dasar IPA</title><link rel="stylesheet" href="{prefix}styles.css"><link rel="stylesheet" href="{prefix}course.css"></head><body><a class="skip" href="#main">Lewati navigasi</a>{nav(prefix)}<main id="main">{body}</main><footer class="footer"><div class="wrap"><span>Konsep Dasar IPA · PGMI · InkuiriLab</span><a href="{prefix}index.html#topik">Semua topik ↑</a></div></footer>{script}</body></html>'
def link(t,prefix=''):return f'{prefix}topik/{t["slug"]}/index.html'
for n,t in enumerate(TOPICS,1):
 slug=t['slug'];p='../../';idx={m[0]:m for m in MEETINGS};meet=[m[0] for m in MEETINGS if slug in m[2]][0]
 goals=''.join(f'<li>{e(g)}</li>' for g in t['goals'])
 sections=''.join(f'<section class="concept"><h3>{e(h)}</h3><p class="question">{e(q)}</p><p>{e(body)}</p></section>' for h,q,body in t['sections'])
 cases=''.join(f'<button type="button" data-case="{i}" aria-pressed="{str(i==0).lower()}" aria-controls="explore-panel">{e(c[1])}</button>' for i,c in enumerate(t['cases']))
 panels=''
 for i,(key,title,q,answer) in enumerate(t['cases']):
  panels+=f'<div data-panel="{i}" {"hidden" if i else ""}><figure class="visual">{visual(slug,key)}<figcaption>{e(title)} · skema konseptual, bukan gambar berskala.</figcaption></figure><p class="question">{e(q)}</p><details class="explanation"><summary>Buka penjelasan setelah membuat dugaan</summary><p>{e(answer)}</p></details></div>'
 activity=''.join(f'<li>{e(s)}</li>' for s in t['activity'])
 fallback='<ul>'+''.join(f'<li><strong>{e(c[1])}</strong>: {e(c[3])}</li>' for c in t['cases'])+'</ul>'
 checks=''.join(f'<details class="card check"><summary>{i}. {e(q)}</summary><p>{e(ans)}</p></details>' for i,(q,ans) in enumerate(t['checks'],1))
 note='Halaman ini menjadi bahan belajar dan referensi. Pertemuan gabungan memakai pilihan konsep inti pada peta semester.'
 speed='''<div class="card speed"><h3>Bandingkan jarak dan waktu</h3><p>Untuk perjalanan sederhana, kelajuan rata-rata diperoleh dari jarak dibagi waktu. Perhitungan ini tidak menyatakan arah gerak.</p><label for="distance">Jarak perjalanan (meter)</label><input id="distance" type="number" min="0" max="10000" step="any" value="10"><label for="duration">Waktu tempuh (sekon)</label><input id="duration" type="number" min="0.1" max="10000" step="any" value="5"><p id="speedResult" role="status"></p></div>''' if slug=='gaya' else ''
 prev=f'<a class="btn light" href="../{TOPICS[n-2]["slug"]}/index.html">← Topik sebelumnya</a>' if n>1 else ''
 nxt=f'<a class="btn" href="../{TOPICS[n]["slug"]}/index.html">Topik berikutnya →</a>' if n<len(TOPICS) else '<a class="btn" href="../../semester.html">Tinjau semester →</a>'
 body=f'''<div class="wrap crumb"><a href="../../index.html">Semua topik</a> / {n:02} · Pertemuan {meet}</div>
<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">{e(t['group'])} / PGMI</span><h1 class="module-title">{e(t['title'])}</h1><p class="lead">{e(t['opening'])}</p><div class="buttons"><a class="btn" href="#konsep">Telusuri konsep ↓</a><a class="btn light" href="#eksplorasi">Buka visual</a></div></div><div class="hero-visual">{visual(slug,t['cases'][0][0]).replace('id="a','id="hero-a').replace('url(#a','url(#hero-a')}</div></div></section>
<div class="wrap strip"><span>Topik {n:02} dari 16</span><span>Teori · Visual · Aplikasi sehari-hari</span><span><a href="../../semester.html#p{meet}">Lihat alokasi pertemuan {meet}</a></span></div>
<nav class="wrap anchor-nav" aria-label="Bagian topik"><a href="#tujuan">Tujuan</a><a href="#konsep">Konsep</a><a href="#eksplorasi">Eksplorasi visual</a><a href="#kegiatan">Kegiatan</a><a href="#cek">Cek pemahaman</a><a href="#refleksi">Refleksi</a></nav>
<section class="section" id="tujuan"><div class="wrap two"><article class="card"><h2 class="small-heading">Setelah belajar, Anda dapat</h2><ul>{goals}</ul></article><article class="card"><h2 class="small-heading">Cara menggunakan materi</h2><p>Jawab pertanyaan awal sebelum membaca. Pada visual, pilih kondisi, buat dugaan, lalu buka penjelasan. Catat bukti yang membuat penjelasan Anda berubah.</p><p class="small">{note}</p></article></div></section>
<section class="section" id="konsep"><div class="wrap content"><span class="eyebrow">Dari pertanyaan menuju penjelasan</span><h2>Bangun pemahaman</h2>{sections}{speed}</div></section>
<section class="section" id="eksplorasi"><div class="wrap content"><span class="eyebrow">Amati dan bandingkan</span><h2>Pilih keadaan untuk ditelusuri</h2><p>Gambar membantu menalar hubungan. Tidak semua bagian alam ditampilkan; gunakan penjelasan untuk mengenali batas model.</p><div class="presets case-buttons" role="group" aria-label="Pilihan visual">{cases}</div><div class="card explore-panel" id="explore-panel">{panels}</div><p id="caseStatus" class="small" role="status">Visual {e(t['cases'][0][1])} ditampilkan.</p><noscript><p>JavaScript tidak aktif. Berikut seluruh visual dan penjelasannya.</p>{fallback}</noscript></div></section>
<section class="section" id="kegiatan"><div class="wrap content"><span class="eyebrow">Pekerjaan mahasiswa</span><h2>Gunakan konsep pada kasus nyata</h2><ol class="activity-list">{activity}</ol><p class="small">Keluaran: satu catatan pengamatan atau gambar berlabel dan penjelasan alasannya. Bila alat atau kondisi tidak memungkinkan, gunakan analisis gambar atau kasus pada halaman ini.</p></div></section>
<section class="section" id="cek"><div class="wrap content"><h2>Periksa pemahaman Anda</h2><p>Jawab lebih dahulu. Buka pembahasan untuk menilai alasan, lalu perbaiki penjelasan bila diperlukan.</p>{checks}</div></section>
<section class="section" id="refleksi"><div class="wrap content"><h2>Refleksi calon guru MI</h2><p class="question">{e(t['reflection'])}</p><div class="card notes"><label for="notes">Catatan belajar</label><p class="small">Tuliskan dugaan awal, hasil pengamatan, penjelasan akhir, dan cara menyampaikannya kepada anak.</p><textarea id="notes" placeholder="Dugaan awal…&#10;Bukti atau pengamatan…&#10;Penjelasan yang diperbaiki…&#10;Cara menjelaskan kepada siswa MI…"></textarea><div class="buttons"><button type="button" id="download" class="btn">Unduh catatan</button><button type="button" id="print" class="btn light">Cetak halaman</button></div><p id="notesStatus" class="small" role="status">Catatan disimpan pada peramban ini jika tersedia. Catatan tidak dikirim ke dosen.</p></div><h3 style="margin-top:28px">Bacaan pendukung</h3><p class="small">{e(t['source'][0])} <a href="{e(t['source'][1])}" target="_blank" rel="noopener">Buka sumber</a>. Penjelasan pada halaman ini disusun secara konseptual untuk PGMI; ilustrasi merupakan model buatan untuk pembelajaran.</p><div class="buttons">{prev}{nxt}</div></div></section>'''
 save(f'topik/{slug}/index.html',page(t['title'],body,p,'<script src="../../learn.js" defer></script>'))

cards=''.join(f'<article class="topic available"><div class="number">{i:02}</div><span class="tag">{e(t["group"])}</span><h3>{e(t["title"])}</h3><p>{e(t["goals"][0])}</p><a class="link" href="{link(t)}">Pelajari topik →</a></article>' for i,t in enumerate(TOPICS,1))
home=f'''<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">Konsep Dasar IPA / PGMI</span><h1>Memahami IPA<br>dari kehidupan.</h1><p class="lead">Materi satu semester untuk calon guru MI. Mulai dari fenomena, telusuri penjelasan melalui visual, lalu gunakan konsep untuk memahami kejadian sehari-hari.</p><div class="buttons"><a class="btn" href="semester.html">Buka peta pertemuan →</a><a class="btn light" href="#topik">Pilih topik</a></div></div><div class="hero-visual">{visual('ekosistem','jaring')}</div></div></section><div class="wrap strip"><span>16 topik tersedia</span><span>14 sesi pembelajaran + UTS + UAS</span><span>Pendekatan konseptual dan visual</span></div><section class="section" id="topik"><div class="wrap"><h2>Semua topik</h2><p class="lead">Pembahasan fisika menggunakan penjelasan kualitatif. Perhitungan sederhana tersedia hanya untuk jarak, waktu, dan kelajuan.</p><div class="grid">{cards}</div></div></section><section class="section"><div class="wrap two"><article class="card"><h3>Belajar melalui pertanyaan</h3><p>Setiap halaman menghubungkan fenomena, teori, eksplorasi visual, kegiatan, dan refleksi. Tulis alasan sebelum membuka pembahasan.</p></article><article class="card"><h3>Catatan dan asesmen</h3><p>Catatan dapat disimpan pada perangkat dan diunduh. Website ini tidak merekam kehadiran atau mengirim nilai ke dosen. Soal UTS dan UAS disediakan sebagai latihan esai, bukan ujian daring terkendali.</p></article></div></section>'''
save('index.html',page('Beranda',home))

lookup={t['slug']:t for t in TOPICS};rows=''
for num,title,slugs,focus in MEETINGS:
 links=' · '.join(f'<a href="{link(lookup[s])}">{e(lookup[s]["title"])}</a>' for s in slugs) if slugs else f'<a href="asesmen/{"uts" if num==8 else "uas"}.html">Buka latihan dan rubrik</a>'
 timing='Pemantik 10 · penjelasan 30 · eksplorasi 15 · kegiatan 25 · cek 15 · refleksi 5 menit.' if len(slugs)==1 else ('Pengantar 10 · konsep inti topik pertama 35 · konsep inti topik kedua 35 · sintesis dan refleksi 20 menit.' if slugs else 'Latihan esai mandiri 80 · refleksi dan pemeriksaan kelengkapan 20 menit; durasi ujian resmi mengikuti ketentuan dosen.')
 core=''
 if num==7:core='Konsep inti: sumber getaran dan medium bunyi; jalur sumber–benda–mata, bayangan dan pemantulan. Tinggi nada, pembiasan, dan warna menjadi bacaan pengayaan; pilih satu kegiatan perbandingan gambar, bukan semua aktivitas dari kedua halaman.'
 if num==11:core='Konsep inti: fungsi akar–batang–daun serta struktur tubuh hewan terkait fungsi. Transport tumbuhan, reproduksi, dan detail daur hidup menjadi pengayaan; gunakan satu tugas perbandingan tumbuhan–hewan.'
 rows+=f'<article class="card meeting" id="p{num}"><span class="eyebrow">Pertemuan {num:02}</span><h2 class="small-heading">{e(title)}</h2><p>{e(focus)}</p><p>{links}</p>{f"<p>{e(core)}</p>" if core else ""}<p class="small">{timing}</p></article>'
save('semester.html',page('Peta Semester',f'<section class="hero"><div class="wrap content"><span class="eyebrow">Rancangan pembelajaran</span><h1 class="module-title">Satu semester<br>Konsep Dasar IPA</h1><p class="lead">Rancangan 16 pertemuan, termasuk UTS dan UAS. Alokasi sesi belajar 100 menit. Peta ini merupakan bahan perencanaan pembelajaran, bukan pengganti RPS resmi.</p><p>Seluruh 16 topik sumber tetap disediakan. Dua sesi menggabungkan topik berdekatan dengan pembatasan konsep inti agar beban pertemuan realistis. Bacaan pengayaan tidak harus dituntaskan di kelas.</p></div></section><section class="section"><div class="wrap content">{rows}<div class="buttons"><a class="btn light" href="kalibrasi.html">Lihat catatan kalibrasi</a></div></div></section>'))

EXAMS={
 'uts':('UTS',[('Pengamatan dan inferensi','Seorang siswa mengatakan gelas dingin basah karena bocor. Bedakan pengamatan dan penjelasannya, lalu usulkan pembanding.'),('Zat dan perubahan','Bandingkan es mencair dengan kertas terbakar. Jelaskan bukti dan batas pengamatan yang mendukung klasifikasi.'),('Gaya dan usaha','Buku didorong, lalu berhenti setelah tangan dilepas. Jelaskan penyebab perubahan gerak dan bedakan menggeser buku dari menahannya diam.'),('Energi dan suhu','Jelaskan perubahan energi pada senter serta mengapa sendok logam terasa lebih dingin daripada kayu yang berada di ruangan sama.'),('Bunyi dan cahaya','Jelaskan jalur yang memungkinkan kita mendengar bel dan melihat buku. Sebutkan kesamaan atau perbedaan peran medium pada keduanya.')]),
 'uas':('UAS',[('Listrik dan keselamatan','Jelaskan mengapa senter dapat mati walaupun baterainya masih ada. Rancang penjelasan visual yang aman bagi siswa MI.'),('Organisme dan fungsi','Bandingkan satu struktur tumbuhan dan satu struktur hewan. Hubungkan dengan fungsi tanpa menyatakan organisme membentuk organ karena keinginan sadar.'),('Sistem manusia','Ceritakan hubungan makanan, udara, pencernaan, pernapasan, dan peredaran darah dalam mendukung aktivitas tubuh.'),('Ekosistem dan lingkungan','Buat jaring makanan sederhana, jelaskan arah panah serta peran pengurai. Hubungkan satu perubahan lingkungan dengan kemungkinan dampak dan batas prediksi.'),('Bumi dan antariksa','Bedakan cuaca–iklim, siang–malam, serta fase–gerhana Bulan. Pilih satu model untuk siswa dan sebutkan bagian yang disederhanakan.')])}
for key,(title,qs) in EXAMS.items():
 items=''.join(f'<li><h3>{e(h)}</h3><p>{e(q)}</p></li>' for h,q in qs)
 rubric='<div class="table-wrap"><table><thead><tr><th>Aspek per jawaban</th><th>Skor maksimum</th><th>Acuan</th></tr></thead><tbody><tr><td>Ketepatan konsep</td><td>8</td><td>Konsep utama tepat, tanpa miskonsepsi mendasar.</td></tr><tr><td>Alasan dan bukti</td><td>6</td><td>Penjelasan menghubungkan gejala dengan konsep dan bukti relevan.</td></tr><tr><td>Contoh atau model</td><td>4</td><td>Contoh sesuai dan batas model dikenali.</td></tr><tr><td>Kejelasan</td><td>2</td><td>Istilah dan alur mudah diikuti.</td></tr></tbody></table></div>'
 save(f'asesmen/{key}.html',page(f'Latihan {title}',f'<section class="hero"><div class="wrap content"><span class="eyebrow">Asesmen konseptual</span><h1 class="module-title">Latihan Esai {title}</h1><p class="lead">Lima pertanyaan terbuka. Tunjukkan hubungan konsep dan bukti dengan bahasa yang dapat dipahami calon guru MI. Tidak ada perhitungan wajib.</p><p>Ini latihan terbuka, bukan naskah ujian rahasia. Dosen dapat mengadaptasi kasus dan menentukan pelaksanaan. Jawaban ditulis di catatan atau dokumen terpisah; website tidak mengumpulkan jawaban.</p><ol class="activity-list">{items}</ol><h2>Rubrik analitik</h2><p>Setiap jawaban maksimum 20, sehingga lima jawaban maksimum 100. Berikan skor penuh bila aspek terpenuhi secara tepat, sebagian bila belum lengkap, dan nol bila tidak ditampilkan atau keliru seluruhnya. Penilaian tetap memerlukan pertimbangan dosen.</p>{rubric}<div class="buttons"><a class="btn" href="../semester.html">Kembali ke peta semester</a></div></div></section>','../'))

save('kalibrasi.html',page('Catatan Kalibrasi','''<section class="hero"><div class="wrap content"><span class="eyebrow">Catatan penyusunan</span><h1 class="module-title">Kalibrasi materi PGMI</h1><p>Seluruh topik ditinjau pada ketepatan konsep, tingkat pembahasan, hubungan visual dengan penjelasan, keselamatan kegiatan, dan beban pertemuan.</p><ul><li>Rumus fisika dan soal hitungan dihilangkan dari materi utama. Satu kalkulator kelajuan rata-rata tersedia sebagai pengecualian jarak–waktu.</li><li>Gaya dibedakan dari gerak; gaya seimbang dapat terjadi saat diam maupun bergerak lurus berkecepatan tetap.</li><li>Suhu dibedakan dari kalor; partikel tidak membesar saat zat berubah wujud; petunjuk reaksi perlu ditafsirkan.</li><li>Jalur cahaya menuju mata, arti frekuensi–amplitudo, dan rangkaian tertutup diperiksa secara konseptual.</li><li>Fotosintesis dibedakan dari respirasi; adaptasi tidak dijelaskan sebagai keinginan hewan; sistem organ tidak diperlakukan terpisah.</li><li>Panah rantai makanan menunjukkan perpindahan energi; daur materi dibedakan dari aliran energi.</li><li>Cuaca dibedakan dari iklim; fase Bulan dari gerhana; ukuran gambar tata surya bukan skala sebenarnya.</li><li>Visual merupakan skema untuk hubungan tertentu. Teks alternatif dan penjelasan disediakan; panah tidak otomatis menunjukkan besaran kuantitatif.</li><li>Sesi gabungan membatasi konsep inti dan menempatkan cakupan tambahan sebagai pengayaan.</li></ul><p>Kalibrasi ini merupakan pemeriksaan internal bahan ajar. Belum merupakan validasi ahli eksternal atau bukti efektivitas pembelajaran pada mahasiswa. Penyesuaian lanjutan dapat dilakukan berdasarkan pengalaman kelas.</p><div class="buttons"><a class="btn" href="semester.html">Peta semester</a></div></div></section>'''))
print(f'Built {len(TOPICS)} topics, {len(MEETINGS)} meetings, and assessment resources.')
